BEGIN
	DECLARE controles varchar(1000);
    DECLARE controle varchar(300);
    DECLARE done INT DEFAULT 0;
    DECLARE cur1 CURSOR FOR
	select distinct  concat_ws('/',documentos.CODIGO,documentos.TITULO ) as controles
	FROM documentos  
	left join documentosxaspectos on documentosxaspectos.CODDOCUMENTO = documentos.CODDOCUMENTO   
	left join documentosximpactos on documentosximpactos.CODDOCUMENTO = documentos.CODDOCUMENTO  
	left join documentosxatividades on documentosxatividades.CODDOCUMENTO = documentos.CODDOCUMENTO  
	 where  documentos.coddocumento in (select coddocumento from documentosxunidades where codunidade=IN_CODUNIDADE) and 
	 (documentosxaspectos.CODASPECTO=IN_CODASPECTO or documentosximpactos.CODIMPACTO=IN_CODIMPACTO or documentosxatividades.CODATIVIDADE=IN_CODATIVIDADE);
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
    OPEN cur1;
	read_loop: LOOP
		FETCH cur1 INTO controle;
		set controles=concat_ws(';',controles,controle);
	END LOOP;
    CLOSE cur1;
RETURN controles;
END

