DECLARE pdata_de_conhecimento_fornecedor datetime;
DECLARE pdiferencadias int default 0;
    select data_de_criacao into pdata_de_criacao from nc_planodeacao where codcausa in(
	select codcausa from nc_causas where codocorrencia=in_codocorrencia) and
