BEGIN
  DECLARE v_func_id BIGINT UNSIGNED;
  DECLARE v_menu_id BIGINT UNSIGNED;
  DECLARE v_grupo_id BIGINT UNSIGNED;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Falha ao provisionar funcionalidade (transação revertida)';
  END;

  START TRANSACTION;

    -- (1) cria funcionalidade se não existir
    SELECT id INTO v_func_id FROM seg_funcionalidade WHERE codigo=p_codigo LIMIT 1;
    IF v_func_id IS NULL THEN
      INSERT INTO seg_funcionalidade (codigo, nome, descricao, modulo, prefixo, ativo)
      VALUES (p_codigo, p_nome, p_desc, p_modulo, p_prefixo, 1);
      SET v_func_id = LAST_INSERT_ID();
    END IF;

    -- (2) cria menu padrão se não existir
    SELECT m.id INTO v_menu_id
    FROM seg_menu m
    WHERE m.funcionalidade_id = v_func_id
    LIMIT 1;

    IF v_menu_id IS NULL THEN
      INSERT INTO seg_menu (nome, rota, funcionalidade_id, ordem, ativo)
      VALUES (CONCAT('Menu - ', p_nome), CONCAT('/app/', LOWER(p_prefixo), LOWER(p_codigo)), v_func_id, 0, 1);
      SET v_menu_id = LAST_INSERT_ID();
    END IF;

    -- (3) concede ao grupo (se informado)
    IF p_grupo_nome IS NOT NULL AND p_grupo_nome <> '' THEN
      SELECT id INTO v_grupo_id FROM seg_grupo WHERE nome=p_grupo_nome LIMIT 1;
      IF v_grupo_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Grupo informado não existe';
      END IF;

      -- upsert simples em seg_grupo_funcionalidade
      IF EXISTS (SELECT 1 FROM seg_grupo_funcionalidade WHERE grupo_id=v_grupo_id AND funcionalidade_id=v_func_id) THEN
        UPDATE seg_grupo_funcionalidade
           SET pode_ver=p_ver, pode_criar=p_criar, pode_editar=p_editar,
               pode_aprovar=p_aprovar, pode_excluir=p_excluir, pode_baixar=p_baixar, pode_imprimir=p_imprimir
         WHERE grupo_id=v_grupo_id AND funcionalidade_id=v_func_id;
      ELSE
        INSERT INTO seg_grupo_funcionalidade (
          grupo_id, funcionalidade_id, pode_ver, pode_criar, pode_editar,
          pode_aprovar, pode_excluir, pode_baixar, pode_imprimir
        ) VALUES (
          v_grupo_id, v_func_id, p_ver, p_criar, p_editar,
          p_aprovar, p_excluir, p_baixar, p_imprimir
        );
      END IF;

      -- (opcional) relaciona menu ao grupo se ainda não existir
      IF NOT EXISTS (SELECT 1 FROM seg_grupo_menu WHERE grupo_id=v_grupo_id AND menu_id=v_menu_id) THEN
        INSERT INTO seg_grupo_menu (grupo_id, menu_id) VALUES (v_grupo_id, v_menu_id);
      END IF;
    END IF;

  COMMIT;

  -- retorna IDs criados/localizados
  SELECT v_func_id AS funcionalidade_id, v_menu_id AS menu_id, v_grupo_id AS grupo_id;
END

BEGIN
  SET @rownum := 0;

  IF p_criterio = 'nome' THEN
    UPDATE seg_menu m
    JOIN (
      SELECT id, (@rownum := @rownum + 1) AS nova_ordem
      FROM seg_menu
      ORDER BY nome, id
    ) seq ON seq.id = m.id
    SET m.ordem = seq.nova_ordem;

  ELSEIF p_criterio = 'rota' THEN
    SET @rownum := 0;
    UPDATE seg_menu m
    JOIN (
      SELECT id, (@rownum := @rownum + 1) AS nova_ordem
      FROM seg_menu
      ORDER BY rota, id
    ) seq ON seq.id = m.id
    SET m.ordem = seq.nova_ordem;

  ELSEIF p_criterio = 'funcionalidade' THEN
    SET @rownum := 0;
    UPDATE seg_menu m
    JOIN (
      SELECT m2.id, (@rownum := @rownum + 1) AS nova_ordem
      FROM seg_menu m2
      JOIN seg_funcionalidade f ON f.id = m2.funcionalidade_id
      ORDER BY f.modulo, f.prefixo, f.codigo, m2.id
    ) seq ON seq.id = m.id
    SET m.ordem = seq.nova_ordem;

  ELSE -- default: 'id'
    SET @rownum := 0;
    UPDATE seg_menu m
    JOIN (
      SELECT id, (@rownum := @rownum + 1) AS nova_ordem
      FROM seg_menu
      ORDER BY id
    ) seq ON seq.id = m.id
    SET m.ordem = seq.nova_ordem;
  END IF;
END

