  IF p_login IS NULL OR p_login = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Login obrigatório';
  END IF;
  IF EXISTS (SELECT 1 FROM seg_usuario WHERE login=p_login) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Login já existente';
  END IF;

  INSERT INTO seg_usuario (login, nome, email, senha_hash, ativo, criado_em)
  VALUES (p_login, p_nome, p_email, SHA2(p_senha_plain,256), COALESCE(p_ativo,1), NOW());

  SELECT * FROM seg_usuario WHERE id = LAST_INSERT_ID();
END

BEGIN
  DECLARE v_limit  INT DEFAULT 100;
  DECLARE v_offset INT DEFAULT 0;
  SET v_limit  = COALESCE(p_limit, 100);
  SET v_offset = COALESCE(p_offset, 0);

  SELECT u.*
  FROM seg_usuario u
  WHERE (p_ativo = -1 OR u.ativo = p_ativo)
    AND (p_like IS NULL
         OR u.nome  LIKE CONCAT('%',p_like,'%')
         OR u.email LIKE CONCAT('%',p_like,'%')
         OR u.login LIKE CONCAT('%',p_like,'%'))
  ORDER BY u.id
  LIMIT v_offset, v_limit;
END

BEGIN
