  UPDATE seg_usuario
     SET nome = p_nome,
         email = p_email,
         ativo = p_ativo,
         atualizado_em = NOW()
   WHERE id = p_id;

  IF p_senha_plain IS NOT NULL THEN
    UPDATE seg_usuario
       SET senha_hash = SHA2(p_senha_plain,256),
           atualizado_em = NOW()
     WHERE id = p_id;
  END IF;

  SELECT * FROM seg_usuario WHERE id=p_id;
END

