begin
    DECLARE done INT DEFAULT FALSE;
	DECLARE patendido varchar(20);
	DECLARE tatendido int;
	DECLARE tot_s int default 0;
	DECLARE tot_n int default 0;
	DECLARE tot_i int default 0;
    DECLARE tot_pa int default 0;
	
	DECLARE atendidos CURSOR FOR 
	select atendido,count(atendido) as total from 
    legislacaoxsituacao where codlegislacao=in_codlegislacao and codunidade=in_codunidade group by atendido;  
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	open atendidos;
	ratendidos: LOOP
		FETCH atendidos INTO patendido,tatendido;
        if patendido='PA' then
			set tot_pa=tatendido;
		end if;
        if patendido='AI' then
			set tot_i=tatendido;
		end if;		
		if patendido='S' then
			set tot_s=tatendido;
		end if;
		if patendido='N' then
			set tot_n=tatendido;
		end if;	
		if patendido<>'N' and patendido<>'S' then
			set tot_i=tatendido;
		end if;
        IF done THEN
          LEAVE ratendidos;
        END IF;		
	END LOOP;
	CLOSE atendidos;
	if tot_pa>0  then
		return 'Parcialmente Atendido';
	end if;	
	if tot_n>0 and tot_s>0 then
		return 'Parcialmente Atendido';
	end if;	    
	if tot_s>0 and tot_i>0 then
		return 'Atendimento indefinido!';
	end if;	
	if tot_n>0 and tot_i>0 then
		return 'Não';
	end if;	
	if tot_i>0 and tot_s>0 and tot_n>0 then
		return 'Atendimento indefinido!';
	end if;
	if tot_s>0 and tot_n=0 and tot_i=0 then
		return 'Sim';
	end if;
	if tot_s>0 then
		return 'Sim';
	end if;
	if tot_n>0 then
		return 'Não';
	end if;
	if tot_i>0 then
		return 'Atendimento indefinido!';
	end if;
	return 'Atendimento indefinido!';
end

