begin
	DECLARE done INT DEFAULT FALSE;
    DECLARE pqtddias int default 0;
	DECLARE pstatus int default 0;

	DECLARE cur_qtddias CURSOR FOR 	
	select 
	distinct if(year(datafinal) = 0, -100, datediff(datafinal,now())) as qtddias,
	status 
	from nc_planodeacao 
	where codcausa in (select codcausa from nc_causas where codocorrencia = in_codocorrencia) and 
    status < 100 and codusuario=in_codusuario
	union all 
	select 
	distinct if(year(datafinal) = 0, -100, datediff(datafinal,now())) as qtddias,
	status 
	from nc_planodeacao 
	where codocorrencia=in_codocorrencia and status<100 and codusuario=in_codusuario
	order by 1 asc;
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	open cur_qtddias;
	rcur_qtddias: LOOP
		FETCH cur_qtddias INTO pqtddias,pstatus;
        IF done THEN
          LEAVE rcur_qtddias;
        END IF;	        
	END LOOP;
	CLOSE cur_qtddias;
	return pqtddias;
end

begin
DECLARE done INT DEFAULT FALSE;
DECLARE ret_status VARCHAR(3) DEFAULT 'Sim';
DECLARE cur_status int;
DECLARE nc_planodeacao_status int;
DECLARE total int;

DECLARE ocorrencias CURSOR FOR 
select status from nc_planodeacao where 
codcausa in(select codcausa from nc_causas where codocorrencia=in_codocorrencia)
order by status desc;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

select count(status) into nc_planodeacao_status from nc_planodeacao where 
codcausa in(select codcausa from nc_causas where codocorrencia=in_codocorrencia)
order by status desc;

select COUNT(codcausa) into total from nc_causas
where codocorrencia=in_codocorrencia and
codcausa not in(select codcausa from nc_planodeacao);
if nc_planodeacao_status=0 then
    return 'N';
end if;
if total=0 then
    OPEN ocorrencias;
    rocorrencias: LOOP
        FETCH ocorrencias INTO cur_status;
        IF cur_status<100 THEN
           set ret_status='N';
        END IF;
        IF done THEN
          LEAVE rocorrencias;
        END IF;
    END LOOP;
    CLOSE ocorrencias;
    return ret_status;
else
    return 'N';
end if;
end

