BEGIN
    DECLARE v_done INT DEFAULT 0;
    DECLARE v_tabela VARCHAR(200);
    DECLARE v_base VARCHAR(200);
    DECLARE v_base_singular VARCHAR(200);
    DECLARE v_colunas LONGTEXT;
    DECLARE v_select LONGTEXT;
    DECLARE v_sql LONGTEXT;
    DECLARE v_novo_codtransacao INT;
    DECLARE v_existe INT DEFAULT 0;

    DECLARE cur_tabelas CURSOR FOR
        SELECT TABLE_NAME
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = 'hpr_configuracoes'
          AND LOWER(COLUMN_NAME) = 'codtransacao'
          AND TABLE_NAME <> 'configuracoes_transacoes'
        GROUP BY TABLE_NAME
        ORDER BY TABLE_NAME;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SET SESSION group_concat_max_len = 1000000;

    START TRANSACTION;

    SELECT COUNT(*)
      INTO v_existe
    FROM hpr_configuracoes.configuracoes_transacoes
    WHERE codtransacao = p_codtransacao_origem;

    IF v_existe = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'codtransacao de origem não encontrado.';
    END IF;

    /*
      Duplica a tabela principal.
      O codtransacao não entra no INSERT porque é AUTO_INCREMENT.
    */
    SELECT
        GROUP_CONCAT(CONCAT('`', COLUMN_NAME, '`') ORDER BY ORDINAL_POSITION SEPARATOR ', '),
        GROUP_CONCAT(
            CASE
                WHEN LOWER(COLUMN_NAME) = 'dsctransacao'
                    THEN CONCAT('CONCAT('(d) ', IFNULL(`', COLUMN_NAME, '`, ''))')
                ELSE CONCAT('`', COLUMN_NAME, '`')
            END
            ORDER BY ORDINAL_POSITION SEPARATOR ', '
        )
    INTO v_colunas, v_select
    FROM INFORMATION_SCHEMA.COLUMNS
    WHERE TABLE_SCHEMA = 'hpr_configuracoes'
      AND TABLE_NAME = 'configuracoes_transacoes'
      AND EXTRA NOT LIKE '%auto_increment%';

    SET @sql = CONCAT(
        'INSERT INTO hpr_configuracoes.configuracoes_transacoes (', v_colunas, ') ',
        'SELECT ', v_select, ' ',
        'FROM hpr_configuracoes.configuracoes_transacoes ',
        'WHERE codtransacao = ', p_codtransacao_origem
    );

    PREPARE stmt FROM @sql;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;

    SET v_novo_codtransacao = LAST_INSERT_ID();

    /*
      Duplica todas as tabelas filhas que possuem codtransacao.
    */
    OPEN cur_tabelas;

    loop_tabelas: LOOP
        FETCH cur_tabelas INTO v_tabela;

        IF v_done = 1 THEN
            LEAVE loop_tabelas;
        END IF;

        SET v_base = LOWER(REPLACE(v_tabela, 'configuracoes_', ''));

        IF RIGHT(v_base, 1) = 's' THEN
            SET v_base_singular = LEFT(v_base, LENGTH(v_base) - 1);
        ELSE
            SET v_base_singular = v_base;
        END IF;

        SELECT
            GROUP_CONCAT(CONCAT('`', COLUMN_NAME, '`') ORDER BY ORDINAL_POSITION SEPARATOR ', '),
            GROUP_CONCAT(
                CASE
                    WHEN LOWER(COLUMN_NAME) = 'codtransacao'
                        THEN CAST(v_novo_codtransacao AS CHAR)

                    WHEN LOWER(COLUMN_NAME) IN (
                        CONCAT('dsc', v_base),
                        CONCAT('dsc', v_base_singular)
                    )
                        THEN CONCAT('CONCAT('(d) ', IFNULL(`', COLUMN_NAME, '`, ''))')

                    ELSE CONCAT('`', COLUMN_NAME, '`')
                END
                ORDER BY ORDINAL_POSITION SEPARATOR ', '
            )
        INTO v_colunas, v_select
        FROM INFORMATION_SCHEMA.COLUMNS
        WHERE TABLE_SCHEMA = 'hpr_configuracoes'
          AND TABLE_NAME = v_tabela
          AND EXTRA NOT LIKE '%auto_increment%';

        SET @sql = CONCAT(
            'INSERT INTO hpr_configuracoes.`', v_tabela, '` (', v_colunas, ') ',
            'SELECT ', v_select, ' ',
            'FROM hpr_configuracoes.`', v_tabela, '` ',
            'WHERE codtransacao = ', p_codtransacao_origem
        );

        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;

    END LOOP;

    CLOSE cur_tabelas;

    COMMIT;

    SELECT v_novo_codtransacao AS novo_codtransacao;

END

