  IF v_grupo_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Grupo nao encontrado ou inativo';
  END IF;

  SELECT id INTO v_func_id FROM seg_funcionalidade WHERE codigo = p_func_codigo AND ativo=1 LIMIT 1;
  IF v_func_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Funcionalidade nao encontrada ou inativa';
  END IF;

  -- tenta update; se 0 linhas afetadas, faz insert
  UPDATE seg_grupo_funcionalidade
     SET pode_ver=p_ver, pode_criar=p_criar, pode_editar=p_editar,
         pode_aprovar=p_aprovar, pode_excluir=p_excluir,
         pode_baixar=p_baixar, pode_imprimir=p_imprimir
   WHERE grupo_id=v_grupo_id AND funcionalidade_id=v_func_id;

  IF ROW_COUNT() = 0 THEN
    INSERT INTO seg_grupo_funcionalidade(
      grupo_id, funcionalidade_id, pode_ver, pode_criar, pode_editar,
      pode_aprovar, pode_excluir, pode_baixar, pode_imprimir
    ) VALUES (
      v_grupo_id, v_func_id, p_ver, p_criar, p_editar,
      p_aprovar, p_excluir, p_baixar, p_imprimir
    );
  END IF;
