BEGIN
  DECLARE v_src_id BIGINT UNSIGNED;
  DECLARE v_dst_id BIGINT UNSIGNED;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Falha ao clonar grupo (transação revertida)';
  END;

  SELECT id INTO v_src_id FROM seg_grupo WHERE nome=p_grupo_origem_nome LIMIT 1;
  IF v_src_id IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Grupo de origem não encontrado';
  END IF;

  IF EXISTS (SELECT 1 FROM seg_grupo WHERE nome=p_grupo_dest_nome) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Grupo de destino já existe';
  END IF;

  START TRANSACTION;

    INSERT INTO seg_grupo (nome, descricao, ativo, criado_em)
    VALUES (p_grupo_dest_nome, p_grupo_dest_desc, 1, NOW());
    SET v_dst_id = LAST_INSERT_ID();

    -- Copia MENUS
    INSERT INTO seg_grupo_menu (grupo_id, menu_id)
    SELECT v_dst_id, gm.menu_id
    FROM seg_grupo_menu gm
    WHERE gm.grupo_id = v_src_id;

    -- Copia PERMISSÕES (funcionalidades)
    INSERT INTO seg_grupo_funcionalidade (
      grupo_id, funcionalidade_id,
      pode_ver, pode_criar, pode_editar, pode_aprovar, pode_excluir, pode_baixar, pode_imprimir
    )
    SELECT
      v_dst_id, gf.funcionalidade_id,
      gf.pode_ver, gf.pode_criar, gf.pode_editar, gf.pode_aprovar, gf.pode_excluir, gf.pode_baixar, gf.pode_imprimir
    FROM seg_grupo_funcionalidade gf
    WHERE gf.grupo_id = v_src_id;

  COMMIT;

  SELECT * FROM seg_grupo WHERE id=v_dst_id;
END

