  FROM seg_menu m
  JOIN seg_funcionalidade f ON f.id = m.funcionalidade_id
  WHERE (p_ativo=-1 OR m.ativo=p_ativo)
    AND (p_like IS NULL
      OR m.nome LIKE CONCAT('%',p_like,'%')
      OR m.rota LIKE CONCAT('%',p_like,'%')
      OR f.codigo LIKE CONCAT('%',p_like,'%'))
  ORDER BY m.ordem, m.nome
  LIMIT v_offset, v_limit;
