BEGIN
    DECLARE v_banco_base VARCHAR(100);
    DECLARE v_banco_seg VARCHAR(120);

    SET v_banco_base = REGEXP_REPLACE(p_banco_base, '_seguranca$', '');
    SET v_banco_seg = CONCAT(v_banco_base, '_seguranca');

    SET @sql = CONCAT(
        'SELECT 
            CODUSUARIO,
            NOME,
            USERID,
            EMAILS,
            DTINCLUSAO,
            ultimoacesso,
            codfornecedor,
            usuario_licensa,
            codunidade,
            ATIVADO
         FROM `', v_banco_seg, '`.usuarios
         WHERE USERID = ?
         LIMIT 1'
    );

    SET @userid = p_userid;

    PREPARE stmt FROM @sql;
    EXECUTE stmt USING @userid;
    DEALLOCATE PREPARE stmt;
END

