         WHERE u.USERID = ?
         ORDER BY g.DSCGRUPO'
    );

    SET @userid = p_userid;

    PREPARE stmt FROM @sql;
    EXECUTE stmt USING @userid;
    DEALLOCATE PREPARE stmt;
END

